declare(strict_types=1);namespace App\Http\Requests\Hrd;use Illuminate\Foundation\Http\FormRequest;
class SelfAttendanceRequest extends FormRequest{public function authorize():bool{return $this->user()?->can('personnel-attendance.check')===true;}public function rules():array{return ['challenge_id'=>['required','uuid'],'nonce'=>['required','string','size:64'],'device_uuid'=>['nullable','uuid'],'device_name'=>['nullable','string','max:100'],'browser'=>['nullable','string','max:80'],'platform'=>['nullable','string','max:80'],'latitude'=>['nullable','required_if:location_required,1','numeric','between:-90,90'],'longitude'=>['nullable','required_with:latitude','numeric','between:-180,180'],'accuracy'=>['nullable','required_with:latitude','numeric','min:0','max:100000'],'location_captured_at'=>['nullable','required_with:latitude','date'],'altitude'=>['nullable','numeric'],'altitude_accuracy'=>['nullable','numeric','min:0'],'heading'=>['nullable','numeric','between:0,360'],'speed'=>['nullable','numeric','min:0']];}}
